const rows = Array.isArray(listCompanies_v2.data) ? listCompanies_v2.data : [];
const country = startTrigger.params.country;
const filtered = country ? rows.filter(r => String(r.country).toLowerCase() === String(country).toLowerCase()) : rows;
return {
  environment: constants.env,
  total: filtered.length,
  companies: filtered.map(r => ({ id: r.id, name: r.name, country: r.country, employees: r.employeeCount, ceo: r.ceoName }))
};
